eventScripts.script:
# Pattern 5: one manual operation advance, on the rising edge only.
# bes_batch resets this flag when it is finished, and that falling edge
# re-enters here and returns at the third guard.
if initialChange:
	return
if currentValue is None or currentValue.value is None:
	return
if not currentValue.value:
	return
bes_batch.advance(tagPath.rsplit("/", 1)[0])

# Pattern 3: one MQTT publish per HistoricalSampleResults SampleTime change.
# Vendor field, not ICC26Extensions. The event stream reads the historical siblings.
if initialChange:
	return
if currentValue is None or currentValue.value is None:
	return
try:
	if not currentValue.quality.isGood():
		return
except:
	return
base = tagPath.rsplit("/", 1)[0]
system.eventstream.publishEvent("icc-2026", "03_opcua/cell-analyzer-result", str(base), False)
